-- Produkční startovní data ověřená 1. 8. 2026 na uvedených oficiálních veřejných zdrojích.
-- Neobsahuje falešné nabídky, partnery ani brigády. Skript je idempotentní.

on conflict (id) do update set source_url = excluded.source_url, official_domain = excluded.official_domain, format = excluded.format, parser_key = excluded.parser_key, enabled = excluded.enabled, refresh_interval = excluded.refresh_interval, terms_note = excluded.terms_note;

-- Produkční režimy monitoringu jsou oddělené od posledního výsledku synchronizace.
update public.content_sources set source_url='https://is.muni.cz/predmety/obdobi', official_domain='is.muni.cz', parser_key='muni-is-periods', enabled=true, monitoring_mode='automatic_publish', requires_review=false, confidence=0.96 where university_id='muni' and source_type='academic_calendar';
update public.content_sources set source_url='https://is.jamu.cz/predmety/obdobi', official_domain='is.jamu.cz', parser_key='jamu-is-periods', enabled=true, monitoring_mode='automatic_publish', requires_review=false, confidence=0.96 where university_id='jamu' and source_type='academic_calendar';
update public.content_sources set source_url='https://www.fit.vut.cz/study/calendar/', enabled=true, monitoring_mode='automatic_publish', requires_review=false, confidence=0.96 where id='src-vut-fit';
update public.content_sources set source_url='https://www.fme.vutbr.cz/studenti/plan?degree=0&mode=0', enabled=true, monitoring_mode='automatic_publish', requires_review=false, confidence=0.96 where id='src-vut-fsi';
update public.content_sources set enabled=true, monitoring_mode='automatic_publish', requires_review=false, confidence=0.96 where id='src-mendelu-pef';
update public.content_sources set source_url='https://www.vetuni.cz/Rozpis_vyuky_pro_akademicky_rok', official_domain='vetuni.cz', format='html', parser_key='linked-document-review', enabled=true, monitoring_mode='automatic_review', requires_review=true, refresh_interval=interval '1 day' where id in ('src-vetuni-fvl','src-vetuni-fvhe');
update public.content_sources set enabled=true, monitoring_mode='automatic_review', requires_review=true, refresh_interval=interval '1 day' where source_type='academic_calendar' and id not in ('src-vut-fit','src-vut-fsi','src-mendelu-pef','src-mendelu-frrms') and university_id not in ('muni','jamu');
update public.content_sources set parser_key='not-found-monitor', enabled=true, monitoring_mode='not_found_monitored', requires_review=true, confidence=0, refresh_interval=interval '1 day' where id='src-mendelu-frrms';

on conflict (id) do update set title = excluded.title, description = excluded.description, starts_at = excluded.starts_at, ends_at = excluded.ends_at, source_url = excluded.source_url, last_verified_at = excluded.last_verified_at, status = 'approved', is_demo = false;

on conflict (id) do update set name = excluded.name, description = excluded.description, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, opening_hours = excluded.opening_hours, website_url = excluded.website_url, source_url = excluded.source_url, last_verified_at = excluded.last_verified_at, verification_status = 'verified', status = 'approved', is_demo = false;
